INSERT INTO training_milestone (id, description, target_percentage, title, training_id) VALUES
(1, 'Project setup, auto-configuration, REST controllers, and application properties.', 25, 'Spring Boot Foundations', 1),
(2, 'Entity mapping, repositories, transactions, Flyway migrations, and query methods.', 50, 'Data Layer & JPA', 1),
(3, 'Spring Security, JWT tokens, OAuth2 integration, and role-based access control.', 75, 'Security & Authentication', 1),
(4, 'Service discovery, API Gateway, circuit breakers, Docker packaging, and monitoring.', 100, 'Microservices & Deployment', 1),
(5, 'DDL/DML, joins, subqueries, CTEs, and window functions.', 25, 'SQL Fundamentals Review', 2),
(6, 'B-tree, GIN, GiST indexes, EXPLAIN ANALYZE, and query planner hints.', 50, 'Indexing & Query Plans', 2),
(7, 'Range/list/hash partitioning, logical replication, and streaming replication.', 75, 'Partitioning & Replication', 2),
(8, 'Connection pooling (PgBouncer), vacuum, autovacuum tuning, and monitoring.', 100, 'Performance Tuning', 2),
(9, 'Components, JSX, props, state, lifecycle, and virtual DOM reconciliation.', 25, 'React Core Concepts', 3),
(10, 'useState, useEffect, useContext, useMemo, useCallback, and custom hook patterns.', 50, 'Hooks & Custom Hooks', 3),
(11, 'Redux Toolkit, React Query, Zustand, and server state vs client state patterns.', 75, 'State Management', 3),
(12, 'React Testing Library, Jest, code splitting, lazy loading, and Profiler.', 100, 'Testing & Performance', 3),
